create extension if not exists pgcrypto;create table if not exists public.rooms(id uuid primary key default gen_random_uuid(),invite_code text unique not null,created_at timestamptz default now());create table if not exists public.memories(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,title text,event_date date,note text,image_data text,created_at timestamptz default now());create table if not exists public.room_members(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms(id) on delete cascade,device_id text not null,display_name text not null,created_at timestamptz default now(),unique(room_id,device_id));alter table public.rooms enable row level security;alter table public.memories enable row level security;alter table public.room_members enable row level security;create policy "rooms read" on public.rooms for select using(true);create policy "rooms insert" on public.rooms for insert with check(true);create policy "memories read" on public.memories for select using(true);create policy "memories insert" on public.memories for insert with check(true);create policy "members read" on public.room_members for select using(true);create policy "members insert" on public.room_members for insert with check(true);create policy "members update" on public.room_members for update using(true) with check(true);